// The old version kept everything in this browser, at this same address. Read it, never change it,
// and add only the spending that isn't already here.
function readOldVersionSpending(current){
 let raw=null,source='';
 try{raw=localStorage.getItem(APP_KEY);source=APP_KEY;}catch{}
 if(!raw){
  // no main copy: fall back to the newest safety copy the old version made before a change
  try{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith(APP_KEY+'_before'))keys.push(k);}
   for(const k of keys){const v=localStorage.getItem(k);if(v){raw=v;source=k;break;}}}catch{}
 }
 if(!raw)return {found:false,source:'',all:[],fresh:[]};
 let data;try{data=JSON.parse(raw);}catch{return {found:true,broken:true,source,all:[],fresh:[]};}
 const list=Array.isArray(data?.expenses)?data.expenses:Array.isArray(data?.state?.expenses)?data.state.expenses:[];
 const sig=x=>[x.date,Math.round(Number(x.amount)*100),String(x.note||x.category||'').trim().toLowerCase()].join('|');
 const haveIds=new Set(current.expenses.map(x=>x.id)),haveSigs=new Set(current.expenses.map(sig));
 const all=list.filter(x=>x&&validDate(x.date)&&Number.isFinite(Number(x.amount))&&Number(x.amount)>0);
 const fresh=all.filter(x=>!(x.id&&haveIds.has(x.id))&&!haveSigs.has(sig(x)));
 return {found:true,source,all,fresh,version:data?.version};
}
